import{_ as l,a0 as o,w as p,s as d,I as e,x as i,a1 as n,A as t,ao as h}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"遷徙到 Linux：命令列環境 | LCTT x X-CMD","titleTemplate":false,"description":"遷徙到 Linux：命令列環境 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"遷徙到 Linux：命令列環境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"遷徙到 Linux：命令列環境 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180123 Migrating to Linux- The Command Line","title":"遷徙到 Linux：命令列環境","tag":"201804","desc":""},"relativePath":"201804/20180123 Migrating to Linux- The Command Line.md","filePath":"[post].md"}'),c={name:"201804/20180123 Migrating to Linux- The Command Line.md"};function r(g,s,u,k,b,f){const a=o("Link");return p(),d("div",null,[s[20]||(s[20]=e("h1",{id:"遷徙到-linux-命令列環境",tabindex:"-1"},[i("遷徙到 Linux：命令列環境 "),e("a",{class:"header-anchor",href:"#遷徙到-linux-命令列環境","aria-label":"Permalink to “遷徙到 Linux：命令列環境”"},"​")],-1)),s[21]||(s[21]=e("blockquote",null,[e("p",null,"剛接觸 Linux？在這篇教程中將學習如何輕鬆地在命令列列出、移動和編輯文件。")],-1)),s[22]||(s[22]=e("p",null,[e("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/migrate.jpg?itok=2PBkvV7s",alt:""})],-1)),e("p",null,[s[3]||(s[3]=i("這是關於遷徙到 Linux 系列的第四篇文章了。如果您錯過了之前的內容，可以回顧我們之前談到的內容 ",-1)),n(a,{href:"https://linux.cn/article-9212-1.html"},{default:t(()=>[...s[0]||(s[0]=[i("新手之 Linux",-1)])]),_:1}),s[4]||(s[4]=i("、",-1)),n(a,{href:"https://linux.cn/article-9213-1.html"},{default:t(()=>[...s[1]||(s[1]=[i("文件和文件系統",-1)])]),_:1}),s[5]||(s[5]=i("、和 ",-1)),n(a,{href:"https://linux.cn/article-9293-1.html"},{default:t(()=>[...s[2]||(s[2]=[i("圖形環境",-1)])]),_:1}),s[6]||(s[6]=i("。Linux 無處不在，它可以用於運行大部分的網絡服務器，如 Web、email 和其他服務器；它同樣可以在您的手機、汽車控制台和其他很多設備上使用。現在，您可能會開始好奇 Linux 系統，並對學習 Linux 的工作原理萌發興趣。",-1))]),s[23]||(s[23]=h(`<p>在 Linux 下，命令列非常實用。Linux 的桌面系統中，儘管命令列只是可選操作，但是您依舊能看見很多朋友開着一個命令列窗口和其他應用窗口並肩作戰。在互聯網服務器上和在設備中運行 Linux 時（LCTT 譯註：指 IoT），命令列通常是唯一能直接與操作系統交互的工具。因此，命令列是有必要了解的，至少應當涉獵一些基礎命令。</p><p>在命令列（通常稱之為 Linux shell）中，所有操作都是通過鍵入命令完成。您可以執行查看文件列表、移動文件位置、顯示文件內容、編輯文件內容等一系列操作，通過命令列，您甚至可以查看網頁中的內容。</p><p>如果您在 Windows（CMD 或者 PowerShell） 上已經熟悉關於命令列的使用，您是否想跳轉到“Windows 命令列用户”的章節上去？先閲讀這些內容吧。</p><h3 id="導航" tabindex="-1">導航 <a class="header-anchor" href="#導航" aria-label="Permalink to “導航”">​</a></h3><p>在命令列中，這裏有一個當前工作目錄（文件夾和目錄是同義詞，在 Linux 中它們通常都被稱為目錄）的概念。如果沒有特別指定目錄，許多命令的執行會在當前目錄下生效。比如，鍵入 <code>ls</code> 列出文件目錄，當前工作目錄的文件將會被列舉出來。看一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>Desktop Documents Downloads Music Pictures README.txt Videos</span></span></code></pre></div><p><code>ls Documents</code> 這條命令將會列出 <code>Documents</code> 目錄下的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls Documents</span></span>
<span class="line"><span>report.txt todo.txt EmailHowTo.pdf</span></span></code></pre></div><p>通過 <code>pwd</code> 命令可以顯示當前您的工作目錄。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/student</span></span></code></pre></div><p>您可以通過 <code>cd</code> 命令改變當前目錄並切換到您想要抵達的目錄。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/student</span></span>
<span class="line"><span>$ cd Downloads</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/student/Downloads</span></span></code></pre></div><p>路徑中的目錄由 <code>/</code>（左斜槓）字符分隔。路徑中有一個隱含的層次關係，比如 <code>/home/student</code> 目錄中，home 是頂層目錄，而 <code>student</code> 是 <code>home</code> 的子目錄。</p><p>路徑要麼是絕對路徑，要麼是相對路徑。絕對路徑由一個 <code>/</code> 字符打頭。</p><p>相對路徑由 <code>.</code> 或者 <code>..</code> 開始。在一個路徑中，一個 <code>.</code> 意味着當前目錄，<code>..</code> 意味着當前目錄的上級目錄。比如，<code>ls ../Documents</code> 意味着在此尋找當前目錄的上級名為 <code>Documents</code> 的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/student</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>Desktop Documents Downloads Music Pictures README.txt Videos</span></span>
<span class="line"><span>$ cd Downloads</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/student/Downloads</span></span>
<span class="line"><span>$ ls ../Documents</span></span>
<span class="line"><span>report.txt todo.txt EmailHowTo.pdf</span></span></code></pre></div><p>當您第一次打開命令列窗口時，您當前的工作目錄被設置為您的家目錄，通常為 <code>/home/&lt;您的登錄名&gt;</code>。家目錄專用於登錄之後存儲您的專屬文件。</p><p>環境變量 <code>$HOME</code> 會展開為您的家目錄，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo $HOME</span></span>
<span class="line"><span>/home/student</span></span></code></pre></div><p>下表顯示了用於目錄導航和管理簡單的文本文件的一些命令摘要。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/table-1_0.png?itok=j4Sgv6Vy" alt=""></p><h3 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to “搜索”">​</a></h3><p>有時我們會遺忘文件的位置，或者忘記了我要尋找的文件名。Linux 命令列有幾個命令可以幫助您搜索到文件。</p><p>第一個命令是 <code>find</code>。您可以使用 <code>find</code> 命令通過文件名或其他屬性搜索文件和目錄。舉個例子，當您遺忘了 <code>todo.txt</code> 文件的位置，我們可以執行下面的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find $HOME -name todo.txt</span></span>
<span class="line"><span>/home/student/Documents/todo.txt</span></span></code></pre></div><p><code>find</code> 程序有很多功能和選項。一個簡單的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find &lt;要尋找的目錄&gt; -name &lt;文件名&gt;</span></span></code></pre></div><p>如果這裏有 <code>todo.txt</code> 文件且不止一個，它將向我們列出擁有這個名字的所有文件的所有所在位置。<code>find</code> 命令有很多便於搜索的選項比如類型（文件或是目錄等等）、時間、大小和其他一些選項。更多內容您可以同通過 <code>man find</code> 獲取關於如何使用 <code>find</code> 命令的幫助。</p><p>您還可以使用 <code>grep</code> 命令搜索文件的特定內容，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>grep &quot;01/02/2018&quot; todo.txt</span></span></code></pre></div><p>這將為您展示 <code>todo</code> 文件中 <code>01/02/2018</code> 所在行。</p><h3 id="獲取幫助" tabindex="-1">獲取幫助 <a class="header-anchor" href="#獲取幫助" aria-label="Permalink to “獲取幫助”">​</a></h3><p>Linux 有很多命令，這裏，我們沒有辦法一一列舉。授人以魚不如授人以漁，所以下一步我們將向您介紹幫助命令。</p><p><code>apropos</code> 命令可以幫助您查找需要使用的命令。也許您想要查找能夠操作目錄或是獲得文件列表的所有命令，但是您不知道該運行哪個命令。您可以這樣嘗試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apropos directory</span></span></code></pre></div><p>要在幫助文檔中，得到一個於 <code>directiory</code> 關鍵字的相關命令列表，您可以這樣操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>apropos &quot;list open files&quot;</span></span></code></pre></div><p>這將提供一個 <code>lsof</code> 命令給您，幫助您列出打開文件的列表。</p><p>當您明確知道您要使用的命令，但是不確定應該使用什麼選項完成預期工作，您可以使用 <code>man</code> 命令，它是 manual 的縮寫。您可以這樣使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>man ls</span></span></code></pre></div><p>您可以在自己的設備上嘗試這個命令。它會提供給您關於使用這個命令的完整信息。</p><p>通常，很多命令都能夠接受 <code>help</code> 選項（比如説，<code>ls --help</code>），列出命令使用的提示。<code>man</code> 頁面的內容通常太繁瑣，<code>--help</code> 選項可能更適合快速瀏覽。</p><h3 id="腳本" tabindex="-1">腳本 <a class="header-anchor" href="#腳本" aria-label="Permalink to “腳本”">​</a></h3><p>Linux 命令列中最貼心的功能之一是能夠運行腳本文件，並且能重複運行。Linux 命令可以存儲在文本文件中，您可以在文件的開頭寫入 <code>#!/bin/sh</code>，後面的行是命令。之後，一旦文件被存儲為可執行文件，您就可以像執行命令一樣運行腳本文件，比如，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>--- contents of get_todays_todos.sh ---</span></span>
<span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span>todays_date=\`date +&quot;%m/%d/%y&quot;\`</span></span>
<span class="line"><span>grep $todays_date $HOME/todos.txt</span></span></code></pre></div><p>腳本可以以一套可重複的步驟自動化執行特定命令。如果需要的話，腳本也可以很複雜，能夠使用循環、判斷語句等。限於篇幅，這裏不細述，但是您可以在網上查詢到相關信息。</p><h3 id="windows-命令列用户" tabindex="-1">Windows 命令列用户 <a class="header-anchor" href="#windows-命令列用户" aria-label="Permalink to “Windows 命令列用户”">​</a></h3><p>如果您對 Windows CMD 或者 PowerShell 程序很熟悉，在命令列輸入命令應該是輕車熟路的。然而，它們之間有很多差異，如果您沒有理解它們之間的差異可能會為之困擾。</p><p>首先，在 Linux 下的 <code>PATH</code> 環境與 Windows 不同。在 Windows 中，當前目錄被認為是該搜索路徑（<code>PATH</code>）中的第一個文件夾，儘管該目錄沒有在環境變量中列出。而在 Linux 下，當前目錄不會明確的放在搜索路徑中。Linux 下設置環境變量會被認為是風險操作。在 Linux 的當前目錄執行程序，您需要使用 <code>./</code>（代表當前目錄的相對目錄表示方式） 前綴。這可能會搞糊塗很多 CMD 用户。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./my_program</span></span></code></pre></div><p>而不是</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>my_program</span></span></code></pre></div><p>另外，在 Windows 環境變量的路徑中是以 <code>;</code>（分號） 分割的。在 Linux 中，由 <code>:</code> 分割環境變量。同樣，在 Linux 中路徑由 <code>/</code> 字符分隔，而在 Windows 目錄中路徑由 <code>\\</code> 字符分割。因此 Windows 中典型的環境變量會像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PATH=&quot;C:\\Program Files;C:\\Program Files\\Firefox;&quot;</span></span></code></pre></div><p>而在 Linux 中看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>PATH=&quot;/usr/bin:/opt/mozilla/firefox&quot;</span></span></code></pre></div><p>還要注意，在 Linux 中環境變量由 <code>$</code> 拓展，而在 Windows 中您需要使用百分號（就是這樣： <code>%PATH%</code>）。</p><p>在 Linux 中，通過 <code>-</code> 使用命令選項，而在 Windows 中，使用選項要通過 <code>/</code> 字符。所以，在 Linux 中您應該：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a_prog -h</span></span></code></pre></div><p>而不是</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a_prog /h</span></span></code></pre></div><p>在 Linux 下，文件拓展名並沒有意義。例如，將 <code>myscript</code> 重命名為 <code>myscript.bat</code> 並不會因此而變得可執行，需要設置文件的執行權限。文件執行權限會在下次的內容中覆蓋到。</p><p>在 Linux 中，如果文件或者目錄名以 <code>.</code> 字符開頭，意味着它們是隱藏文件。比如，如果您申請編輯 <code>.bashrc</code> 文件，您不能在家目錄中找到它，但是它可能真的存在，只不過它是隱藏文件。在命令列中，您可以通過 <code>ls</code> 命令的 <code>-a</code> 選項查看隱藏文件，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -a</span></span></code></pre></div><p>在 Linux 中，普通的命令與 Windows 的命令不盡相同。下面的表格顯示了常用命令中 CMD 命令和 Linux 命令列的差異。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/table-2_0.png?itok=NNc8TZFZ" alt=""></p><hr>`,67)),e("p",null,[s[8]||(s[8]=i("via: ",-1)),n(a,{href:"https://www.linux.com/blog/learn/2018/1/migrating-linux-command-line"},{default:t(()=>[...s[7]||(s[7]=[i("https://www.linux.com/blog/learn/2018/1/migrating-linux-command-line",-1)])]),_:1})]),e("p",null,[s[12]||(s[12]=i("作者：",-1)),n(a,{href:"https://www.linux.com/users/johnbonesio"},{default:t(()=>[...s[9]||(s[9]=[i("John Bonesio",-1)])]),_:1}),s[13]||(s[13]=i(" 譯者：",-1)),n(a,{href:"https://github.com/CYLeft"},{default:t(()=>[...s[10]||(s[10]=[i("CYLeft",-1)])]),_:1}),s[14]||(s[14]=i(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[11]||(s[11]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[17]||(s[17]=i("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[i("LCTT",-1)])]),_:1}),s[18]||(s[18]=i(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[i("Linux中國",-1)])]),_:1}),s[19]||(s[19]=i(" 榮譽推出",-1))])])}const C=l(c,[["render",r]]);export{y as __pageData,C as default};
